#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n, k;
    if (!(cin >> n >> k)) return 0;

    vector<long long> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<long long> b(n);
    for (int i = 0; i < n; ++i) {
        cin >> b[i];
    }

    long long total_base = 0;
    vector<long long> c(n);

    for (int i = 0; i < n; ++i) {
        total_base += max(0LL, a[i] - b[i]);
        c[i] = min(a[i], b[i]);
    }

    sort(c.rbegin(), c.rend());

    int take = min(n, k + 1);
    long long bonus = 0;
    for (int i = 0; i < take; ++i) {
        bonus += c[i];
    }

    cout << total_base + bonus << "\n";

    return 0;
}
